1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'return'
21	  | 'in-rev'
22	  | 'out-rev'
23	  | 'transfer-rev'
24	  | 'count-rev'
25	  | 'arrival-rev'
26	  | 'return-rev';
27	
28	interface LedgerEntry {
29	  seq: number; // 全局流水序号，即提交顺序
30	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
31	  type: EntryType;
32	  product: string;
33	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
34	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
35	  before: number;
36	  after: number;
37	  from?: string; // 调拨（或冲销调拨）的调出仓
38	  to?: string; // 调拨（或冲销调拨）的调入仓
39	  po?: string; // 到货/退货流水：所属采购单编号
40	  arr?: string; // 退货（及冲销退货）流水：原到货单编号
41	  orig?: string; // 冲销流水：被冲销的原单编号
42	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
43	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
44	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
45	}
46	
47	interface DocRecord {
48	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
49	  resultLines: string[]; // 原提交结果，供幂等重放
50	}
51	
52	interface ReversalRecord {
53	  orig: string; // 被冲销的原单编号
54	  resultLines: string[]; // 冲销提交结果，供幂等重放
55	}
56	
57	interface PurchaseRecord {
58	  poId: string;
59	  supplier: string;
60	  wh: string; // 收货仓
61	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
62	  fromTransfer?: string; // 目的采购单：创建它的采购转单编号（普通登记无此字段）
63	  resultLines: string[]; // 登记结果，供幂等重放
64	}
65	
66	interface PoTransferRecord {
67	  tId: string; // 转单编号（与库存/到货/取消/退货/冲销单共用编号空间）
68	  origPo: string; // 原采购编号
69	  destPo: string; // 新目的采购编号（独立采购编号空间，由本转单创建）
70	  supplier: string; // 目的单供应商
71	  wh: string; // 目的单收货仓
72	  qty: Record<string, number>; // 本次转出：商品 -> 数量（合并后，正安全整数）
73	  resultLines: string[]; // 转单提交结果，供幂等重放
74	}
75	
76	interface ArrivalRecord {
77	  poId: string; // 所属采购单
78	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
79	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
80	  resultLines: string[]; // 到货提交结果，供幂等重放
81	}
82	
83	interface CancelRecord {
84	  poId: string; // 所属采购单
85	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
86	  resultLines: string[]; // 取消提交结果，供幂等重放
87	}
88	
89	interface ReturnRecord {
90	  arrId: string; // 原到货单编号
91	  poId: string; // 所属采购单（冗余自原到货单，便于校验与展示）
92	  wh: string; // 原到货单收货仓（退货从该仓当前余量扣减）
93	  qty: Record<string, number>; // 本次退货：商品 -> 数量（合并后，正安全整数）
94	  resultLines: string[]; // 退货提交结果，供幂等重放
95	}
96	
97	interface ReplenishRule {
98	  min: number; // 下限：预计量不高于此值才触发补货（非负安全整数）
99	  target: number; // 目标：补货缺口 = 目标 - 预计量（非负安全整数，恒大于下限）
100	}
101	
102	interface PlanTransfer {
103	  docId: string; // 调拨子单编号（与库存单据共用编号空间，执行时才占用）
104	  product: string;
105	  from: string; // 调出仓
106	  to: string; // 调入仓（缺货仓）
107	  qty: number; // 冻结的调拨数量（正安全整数）
108	}
109	
110	interface PlanPurchase {
111	  poId: string; // 采购子单编号（独立采购编号空间，执行时才占用）
112	  supplier: string;
113	  wh: string; // 收货仓（缺货仓）
114	  product: string;
115	  qty: number; // 冻结的采购数量（正安全整数）
116	}
117	
118	interface PlanSnapshot {
119	  // 涉及商品（出现在任一调拨/采购子单中的商品）在保存时的全部补货规则
120	  rules: Record<string, Record<string, ReplenishRule>>;
121	  // 这些商品各配置仓在保存时的实存
122	  stock: Record<string, Record<string, number>>;
123	  // 这些商品各配置仓在保存时的待到货合计（精确整数十进制字符串，可超安全整数范围）
124	  pending: Record<string, Record<string, string>>;
125	}
126	
127	interface PlanRecord {
128	  planId: string;
129	  transfers: PlanTransfer[]; // 冻结的调拨子单（按建议顺序：商品、缺货仓、来源仓升序）
130	  purchases: PlanPurchase[]; // 冻结的采购子单（按商品、收货仓升序；零采购不建单）
131	  snapshot: PlanSnapshot; // 保存时冻结的核对快照
132	  status: 'pending' | 'executed';
133	  execResultLines?: string[]; // 已执行方案的落单结果原文，供重放（不再核对、不再生效）
134	}
135	
136	interface Store {
137	  version: 1;
138	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
139	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
140	  entries: LedgerEntry[];
141	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
142	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单、退货单）
143	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
144	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
145	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
146	  returns: Record<string, ReturnRecord>; // 退货单去重与结果（与库存单共用编号空间）
147	  poTransfers: Record<string, PoTransferRecord>; // 采购待收转单去重与结果（与库存单共用编号空间，不改库存与流水）
148	  rules: Record<string, Record<string, ReplenishRule>>; // 补货规则：商品 -> 仓库 -> 下限/目标（每组合唯一）
149	  plans: Record<string, PlanRecord>; // 补货方案（独立编号空间；保存不改库存/采购/流水）
150	}
151	
152	const REV_ENTRY_TYPES = new Set<EntryType>([
153	  'in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev', 'return-rev',
154	]);
155	
156	function nullProto<T extends object>(): T {
157	  return Object.create(null) as T;
158	}
159	
160	function emptyStore(): Store {
161	  return {
162	    version: 1,
163	    products: nullProto(),
164	    stock: nullProto(),
165	    entries: [],
166	    docs: nullProto(),
167	    reversals: nullProto(),
168	    purchases: nullProto(),
169	    arrivals: nullProto(),
170	    cancels: nullProto(),
171	    returns: nullProto(),
172	    poTransfers: nullProto(),
173	    rules: nullProto(),
174	    plans: nullProto(),
175	  };
176	}
177	
178	// ---------- 工具 ----------
179	
180	function isPlainObject(v: unknown): v is Record<string, unknown> {
181	  return typeof v === 'object' && v !== null && !Array.isArray(v);
182	}
183	
184	function isNonNegSafeInt(v: unknown): v is number {
185	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
186	}
187	
188	function isPosSafeInt(v: unknown): v is number {
189	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
190	}
191	
192	function trimOrThrow(label: string, raw: string): string {
193	  const s = raw.trim();
194	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
195	  return s;
196	}
197	
198	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
199	function stableStringify(v: unknown): string {
200	  if (isPlainObject(v)) {
201	    return (
202	      '{' +
203	      Object.keys(v)
204	        .sort()
205	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
206	        .join(',') +
207	      '}'
208	    );
209	  }
210	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
211	  return JSON.stringify(v);
212	}
213	
214	// ---------- 数据持久化 ----------
215	
216	function dataPath(dataDir: string): string {
217	  return join(dataDir, DATA_FILENAME);
218	}
219	
220	function loadStore(dataDir: string): Store {
221	  let raw: string;
222	  try {
223	    raw = readFileSync(dataPath(dataDir), 'utf8');
224	  } catch (e) {
225	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
226	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
227	  }
228	
229	  let data: unknown;
230	  try {
231	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
232	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
233	    data = JSON.parse(raw);
234	  } catch {
235	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
236	  }
237	  return validateStore(data);
238	}
239	
240	function validateStore(data: unknown): Store {
241	  const bad = (msg: string): DataError =>
242	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
243	
244	  if (!isPlainObject(data)) throw bad('根节点不是对象');
245	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
246	
247	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
248	  const store = emptyStore();
249	
250	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
251	  for (const [id, name] of Object.entries(data.products)) {
252	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
253	      throw bad('products 中存在非法编号或名称');
254	    store.products[id] = name;
255	  }
256	
257	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
258	  for (const [pid, whs] of Object.entries(data.stock)) {
259	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
260	    const whMap = nullProto<Record<string, number>>();
261	    for (const [wh, qty] of Object.entries(whs)) {
262	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
263	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
264	      whMap[wh] = qty;
265	    }
266	    store.stock[pid] = whMap;
267	  }
268	
269	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
270	  let lastSeq = 0;
271	  for (const e of data.entries as unknown[]) {
272	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
273	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
274	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
275	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
276	    const isOrig =
277	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' ||
278	      e.type === 'arrival' || e.type === 'return';
279	    if (!isRev && !isOrig) throw bad('流水类型非法');
280	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
281	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
282	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
283	    if (e.type === 'count' || e.type === 'count-rev') {
284	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
285	        throw bad('盘点流水账面/实盘量非法');
286	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
287	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
288	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
289	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
290	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined ||
291	          e.arr !== undefined)
292	        throw bad('盘点流水不应携带数量、调拨、采购或退货字段');
293	    } else {
294	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
295	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
296	        throw bad('非盘点流水不应携带盘点字段');
297	      const delta = e.after - e.before;
298	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
299	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
300	          throw bad('调拨流水缺少调出/调入仓');
301	        if (e.po !== undefined || e.arr !== undefined) throw bad('调拨流水不应携带采购或退货字段');
302	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
303	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
304	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
305	      } else {
306	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
307	        // 到货入收货仓、冲销退货补回为增；退货从收货仓扣减、冲销到货扣回为减
308	        const increases =
309	          e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev';
310	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
311	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
312	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
313	          if (e.arr !== undefined) throw bad('到货流水不应携带原到货单字段');
314	        } else if (e.type === 'return' || e.type === 'return-rev') {
315	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('退货流水缺少采购单编号');
316	          if (typeof e.arr !== 'string' || e.arr.trim() === '') throw bad('退货流水缺少原到货单编号');
317	        } else if (e.po !== undefined || e.arr !== undefined) {
318	          throw bad('非到货/退货流水不应携带采购或退货字段');
319	        }
320	      }
321	    }
322	    if (isRev) {
323	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
324	    } else if (e.orig !== undefined) {
325	      throw bad('原始单据流水不应携带冲销标记');
326	    }
327	    store.entries.push(e as unknown as LedgerEntry);
328	  }
329	
330	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
331	  for (const [docId, rec] of Object.entries(data.docs)) {
332	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
333	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
334	      throw bad(`单据 ${docId} 的去重记录非法`);
335	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
336	    const c = rec.content;
337	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
338	      throw bad(`单据 ${docId} 的业务类型非法`);
339	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
340	    for (const [pid, item] of Object.entries(c.items)) {
341	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
342	      if (c.type === 'count') {
343	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
344	          throw bad(`单据 ${docId} 存在非法盘点明细`);
345	      } else if (!isPosSafeInt(item)) {
346	        throw bad(`单据 ${docId} 存在非法明细`);
347	      }
348	    }
349	    if (c.type === 'transfer') {
350	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
351	        throw bad(`单据 ${docId} 的调拨仓非法`);
352	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
353	      throw bad(`单据 ${docId} 的仓库非法`);
354	    }
355	    store.docs[docId] = rec as unknown as DocRecord;
356	  }
357	
358	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
359	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
360	  if (data.purchases !== undefined) {
361	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
362	    for (const [poId, rec] of Object.entries(data.purchases)) {
363	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
364	      if (
365	        !isPlainObject(rec) ||
366	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
367	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
368	        !isPlainObject(rec.ordered) ||
369	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
370	      )
371	        throw bad(`采购单 ${poId} 的记录非法`);
372	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
373	      let fromTransfer: string | undefined;
374	      if (rec.fromTransfer !== undefined) {
375	        if (typeof rec.fromTransfer !== 'string' || rec.fromTransfer.trim() === '')
376	          throw bad(`采购单 ${poId} 的转单来源编号非法`);
377	        fromTransfer = rec.fromTransfer;
378	      }
379	      const ordered = nullProto<Record<string, number>>();
380	      for (const [pid, qty] of Object.entries(rec.ordered)) {
381	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
382	        ordered[pid] = qty;
383	      }
384	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
385	      store.purchases[poId] = {
386	        poId, supplier: rec.supplier, wh: rec.wh, ordered,
387	        ...(fromTransfer !== undefined ? { fromTransfer } : {}),
388	        resultLines: rec.resultLines,
389	      };
390	    }
391	  }
392	
