749	  for (const [poId, po] of Object.entries(store.purchases)) {
750	    const arrived = nullProto<Record<string, bigint>>();
751	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
752	      if (arr.poId !== poId || revOfOrig[arrId] !== undefined) continue;
753	      for (const [pid, q] of Object.entries(arr.qty)) {
754	        arrived[pid] = (arrived[pid] ?? 0n) + BigInt(q);
755	      }
756	    }
