759	      if (ret.poId !== poId || revOfOrig[retId] !== undefined) continue;
760	      for (const [pid, q] of Object.entries(ret.qty)) {
761	        arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
762	        if (arrived[pid] < 0n)
