770	    const cancelled = nullProto<Record<string, bigint>>();
771	    for (const [canId, can] of Object.entries(store.cancels)) {
772	      if (can.poId !== poId || revOfOrig[canId] !== undefined) continue; // 已整单冲销的取消不再计入有效取消
