774	        cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
775	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(po.ordered[pid]))
776	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
777	      }
778	    }
