780	    for (const t of Object.values(store.poTransfers)) {
781	      if (t.origPo !== poId || revOfOrig[t.tId] !== undefined) continue;
782	      for (const [pid, q] of Object.entries(t.qty)) {
783	        cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
784	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(po.ordered[pid]))
785	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消（含转出）合计超过订购量（待到货量为负）`);
786	      }
787	    }
788	    // 目的单的来源转单已冲销：目的单全部订购量计为取消（待收归零、整单关闭）
789	    if (po.fromTransfer !== undefined && revOfOrig[po.fromTransfer] !== undefined) {
790	      for (const [pid, q] of Object.entries(po.ordered)) {
