792	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(q))
793	          throw bad(`采购单 ${poId} 商品 ${pid} 在来源转单冲销后有效到货与有效取消合计超过订购量（待到货量为负）`);
794	      }
795	    }
796	  }
