801	  if (data.rules !== undefined) {
802	    if (!isPlainObject(data.rules)) throw bad('rules 不是对象');
803	    for (const [pid, whs] of Object.entries(data.rules)) {
804	      if (typeof pid !== 'string' || pid.trim() === '') throw bad('rules 中存在非法商品编号');
805	      if (store.products[pid] === undefined) throw bad(`补货规则指向未登记商品 ${pid}`);
806	      if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的补货规则不是对象`);
807	      const whMap = nullProto<Record<string, ReplenishRule>>();
