986	function saveStore(dataDir: string, store: Store): void {
987	  const path = dataPath(dataDir);
988	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
989	  try {
990	    mkdirSync(dataDir, { recursive: true });
991	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
992	    renameSync(tmp, path);
993	  } catch (e) {
994	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
995	  }
996	}
