999	
1000	interface ParsedArgs {
1001	  positionals: string[];
1002	  flags: Record<string, string>;
1003	  multi: Record<string, string[]>;
1004	}
1005	
1006	function parseArgs(
1007	  tokens: string[],
1008	  singles: string[],
1009	  multis: string[] = [],
1010	): ParsedArgs {
1011	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
1012	  const singleSet = new Set(singles);
1013	  const multiSet = new Set(multis);
1014	
1015	  for (let i = 0; i < tokens.length; i++) {
1016	    const tok = tokens[i];
1017	    if (tok.startsWith('--')) {
1018	      let key = tok;
1019	      let value: string | undefined;
1020	      const eq = tok.indexOf('=');
1021	      if (eq >= 0) {
1022	        key = tok.slice(0, eq);
1023	        value = tok.slice(eq + 1);
1024	      }
1025	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
1026	      if (value === undefined) {
1027	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
1028	        value = tokens[++i];
1029	      }
1030	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
1031	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
1032	      else out.flags[key] = value;
1033	    } else {
1034	      out.positionals.push(tok);
1035	    }
1036	  }
1037	  return out;
1038	}
