1097	function parseNonNegInt(label: string, raw: string): number {
1098	  const s = raw.trim();
1099	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
1100	  const n = Number(s);
1101	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
1102	  return n;
1103	}
