1105	function parseCountArgs(tokens: string[]): CountRequest {
1106	  const args = parseArgs(tokens, ['--wh'], ['--item']);
1107	  const docId = args.positionals[0];
1108	  if (docId === undefined || args.positionals.length !== 1)
1109	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
1110	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
1111	
1112	  const items = new Map<string, CountItem>();
1113	  for (const raw of args.multi['--item'] ?? []) {
