1115	    if (parts.length !== 3)
1116	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
1117	    const pid = trimOrThrow('商品编号', parts[0]);
1118	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
