1120	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
1121	    items.set(pid, { expected, actual });
1122	  }
1123	  if (items.size === 0)
1124	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
1125	
1126	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
1127	}
