1279	/**
1280	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
1281	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
1282	 */
1283	function parseImportFile(raw: string): ImportRequest[] {
1284	  let data: unknown;
1285	  try {
1286	    data = JSON.parse(raw);
1287	  } catch (e) {
1288	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
1289	  }
1290	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
1291	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
1292	
1293	  const out: ImportRequest[] = [];
1294	  // 顶层位置一律标注 1 起序号，便于纠正
1295	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
1296	
1297	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
1298	    const v = obj[key];
1299	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
1300	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
1301	    const s = v.trim();
1302	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
1303	    return s;
1304	  };
1305	
1306	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
1307	    for (const k of Object.keys(obj)) {
1308	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
1309	    }
1310	  };
1311	
1312	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
1313	    const v = obj.items;
1314	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1315	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1316	    if (v.length === 0) throw at(i, '商品明细至少一项');
1317	    const merged = new Map<string, number>();
1318	    v.forEach((entry, j) => {
1319	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1320	      const e = entry as Record<string, unknown>;
1321	      checkUnknown(e, ['product', 'qty'], i);
1322	      const pid = e.product;
1323	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1324	      const p = pid.trim();
1325	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1326	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
1327	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
1328	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
1329	      merged.set(p, sum);
1330	    });
1331	    return merged;
1332	  };
1333	
1334	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
1335	    const v = obj.items;
1336	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1337	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1338	    if (v.length === 0) throw at(i, '商品明细至少一项');
1339	    const items = new Map<string, CountItem>();
1340	    v.forEach((entry, j) => {
1341	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1342	      const e = entry as Record<string, unknown>;
1343	      checkUnknown(e, ['product', 'expected', 'actual'], i);
1344	      const pid = e.product;
1345	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1346	      const p = pid.trim();
1347	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1348	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
1349	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
1350	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
1351	      items.set(p, { expected: e.expected, actual: e.actual });
1352	    });
1353	    return items;
1354	  };
1355	
1356	  data.forEach((rawItem, i) => {
1357	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
1358	    const item = rawItem as Record<string, unknown>;
1359	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
1360	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
1361	
1362	    switch (item.type) {
1363	      case 'in':
1364	      case 'out': {
1365	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1366	        const docId = requireString(item, 'id', '单据编号', i);
1367	        const wh = requireString(item, 'wh', '仓库标识', i);
1368	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
1369	        break;
1370	      }
1371	      case 'transfer': {
1372	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
1373	        const docId = requireString(item, 'id', '单据编号', i);
1374	        const from = requireString(item, 'from', '调出仓标识', i);
1375	        const to = requireString(item, 'to', '调入仓标识', i);
1376	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
1377	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
1378	        break;
1379	      }
1380	      case 'count': {
1381	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1382	        const docId = requireString(item, 'id', '单据编号', i);
1383	        const wh = requireString(item, 'wh', '仓库标识', i);
1384	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
1385	        break;
1386	      }
1387	      case 'reverse': {
1388	        checkUnknown(item, ['type', 'id', 'orig'], i);
1389	        const docId = requireString(item, 'id', '冲销单编号', i);
1390	        const orig = requireString(item, 'orig', '原单编号', i);
1391	        out.push({ kind: 'reverse', docId, orig });
1392	        break;
1393	      }
1394	      case 'po': {
1395	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
1396	        const poId = requireString(item, 'id', '采购编号', i);
1397	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1398	        const wh = requireString(item, 'wh', '收货仓标识', i);
1399	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
1400	        break;
1401	      }
1402	      case 'arrival': {
1403	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1404	        const arrId = requireString(item, 'id', '到货单编号', i);
1405	        const poId = requireString(item, 'po', '采购编号', i);
1406	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
1407	        break;
1408	      }
1409	      case 'cancel': {
1410	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1411	        const canId = requireString(item, 'id', '取消单编号', i);
1412	        const poId = requireString(item, 'po', '采购编号', i);
1413	        out.push({ kind: 'cancel', req: { canId, poId, items: parseQtyItems(item, i) } });
1414	        break;
1415	      }
1416	      case 'return': {
1417	        checkUnknown(item, ['type', 'id', 'arrival', 'items'], i);
1418	        const retId = requireString(item, 'id', '退货单编号', i);
1419	        const arrId = requireString(item, 'arrival', '原到货单编号', i);
1420	        out.push({ kind: 'return', req: { retId, arrId, items: parseQtyItems(item, i) } });
1421	        break;
1422	      }
1423	      case 'po-transfer': {
1424	        checkUnknown(item, ['type', 'id', 'orig', 'dest', 'supplier', 'wh', 'items'], i);
1425	        const tId = requireString(item, 'id', '转单编号', i);
1426	        const origPoId = requireString(item, 'orig', '原采购编号', i);
1427	        const destPoId = requireString(item, 'dest', '新目的采购编号', i);
1428	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1429	        const wh = requireString(item, 'wh', '收货仓标识', i);
1430	        if (origPoId === destPoId) throw at(i, '采购转单的原采购与目的采购不能相同');
1431	        out.push({ kind: 'transfer', req: { tId, origPoId, destPoId, supplier, wh, items: parseQtyItems(item, i) } });
1432	        break;
1433	      }
1434	      default:
1435	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival、cancel、return、po-transfer`);
1436	    }
1437	  });
1438	
1439	  return out;
1440	}
