1445	
1446	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
1447	function fmtSigned(n: number): string {
1448	  return n > 0 ? `+${n}` : String(n);
1449	}
1450	
1451	function canonicalContent(req: DocRequest): Record<string, unknown> {
1452	  const items: Record<string, number> = nullProto();
1453	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
1454	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
1455	  return { type: req.type, wh: req.wh!, items };
