1616	  /**
1617	   * 计算某采购单各商品当前“有效到货”：未冲销累计到货 - 未冲销累计退货。
1618	   * 采购转单不产生到货（目的单初始仍全量待收），故不影响有效到货。
1619	   * 累计总量可超过安全整数范围（反复退货、补收），必须用 BigInt 精确累计，
1620	   * 不得因中间累计舍入而改变净量；单票数量本身仍为正安全整数。
1621	   */
1622	  private effectiveArrived(poId: string): Record<string, bigint> {
1623	    const arrived = nullProto<Record<string, bigint>>();
1624	    for (const [arrId, arr] of Object.entries(this.arrivals)) {
1625	      if (arr.poId !== poId || this.reversedOrigs.has(arrId)) continue;
1626	      for (const [pid, q] of Object.entries(arr.qty)) arrived[pid] = (arrived[pid] ?? 0n) + BigInt(q);
1627	    }
1628	    // 未冲销退货抵减有效到货（有未冲销退货的到货单禁止冲销，故其原到货必然计入上行）
1629	    for (const [retId, ret] of Object.entries(this.returns)) {
1630	      if (ret.poId !== poId || this.reversedOrigs.has(retId)) continue;
1631	      for (const [pid, q] of Object.entries(ret.qty)) arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
1632	    }
1633	    return arrived;
1634	  }
