1636	  /**
1637	   * 计算某采购单各商品当前“有效取消”（BigInt 精确累计），三部分：
1638	   * 1) 未冲销取消单的取消量；
1639	   * 2) 本单作为原单由未冲销采购转单转出的量（转出量在原单计入有效取消）；
1640	   * 3) 本单作为目的单且其来源转单已被冲销：目的单全部订购量计为取消（待收归零）。
1641	   */
1642	  private effectiveCancelled(poId: string): Record<string, bigint> {
1643	    const cancelled = nullProto<Record<string, bigint>>();
1644	    for (const [canId, can] of Object.entries(this.cancels)) {
1645	      if (can.poId !== poId || this.reversedOrigs.has(canId)) continue;
1646	      for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
1647	    }
1648	    for (const t of Object.values(this.transfers)) {
1649	      if (t.origPo !== poId || this.reversedOrigs.has(t.tId)) continue;
1650	      for (const [pid, q] of Object.entries(t.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
1651	    }
1652	    const po = this.pos[poId];
1653	    if (po?.fromTransfer !== undefined && this.reversedOrigs.has(po.fromTransfer)) {
1654	      for (const [pid, q] of Object.entries(po.ordered)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
1655	    }
1656	    return cancelled;
1657	  }
