1694	    this.pos[req.poId] = {
1695	      poId: req.poId, supplier: req.supplier, wh: req.wh, ordered, resultLines: reportLines,
1696	    };
1697	    this.newPoIds.push(req.poId);
1698	
1699	    return { duplicate: false, header: this.poHeader(req.poId, this.pos[req.poId]), lines: reportLines };
1700	  }
