1713	    const existed = this.arrivals[req.arrId];
1714	    if (existed !== undefined) {
1715	      if (
1716	        existed.poId !== req.poId ||
1717	        stableStringify(existed.qty) !== stableStringify(canonicalArrivalItems(req.items))
1718	      )
1719	        throw new BizError(`到货单编号 ${req.arrId} 已用于内容不同的单据，拒绝提交`);
1720	      return {
1721	        duplicate: true,
