1738	
1739	    const po = this.pos[req.poId];
1740	    if (po === undefined) throw new BizError(`采购单 ${req.poId} 不存在，拒绝到货`);
1741	
1742	    for (const [pid] of req.items) {
1743	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1744	      if (po.ordered[pid] === undefined)
