        this.additions.push({
          seq: ++this.seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
          qty, before: beforeTo, after: afterTo, from, to,
        });
        reportLines.push(
          `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
        );
