    this.docs[req.docId] = { content, resultLines: reportLines };
    this.newDocIds.push(req.docId);

    const header = `${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`;
    return { duplicate: false, header, lines: reportLines };

