2788	function formatEntry(e: LedgerEntry): string {
2789	  let line: string;
2790	  if (e.type === 'count' || e.type === 'count-rev') {
2791	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
2792	    line =
2793	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
2794	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
2795	  } else {
2796	    let signed: string;
2797	    // 符号必须与前后余量一致：入库/冲销出库/到货/冲销退货/调入方向为增，其余为减
2798	    const increases =
2799	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev' ||
2800	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
2801	        (e.type === 'transfer') === (e.wh === e.to));
2802	    signed = `${increases ? '+' : '-'}${e.qty}`;
2803	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
2804	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
2805	    if (e.po !== undefined) line += `\t采购单=${e.po}`;
2806	    if (e.arr !== undefined) line += `\t原到货单=${e.arr}`;
2807	  }
2808	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
2809	  return line;
2810	}
