2862	function verifyLedgerIntegrity(store: Store): void {
2863	  const lastByCombo = new Map<string, LedgerEntry>();
2864	  for (const e of store.entries) {
2865	    const key = JSON.stringify([e.product, e.wh]);
2866	    const prev = lastByCombo.get(key);
2867	    if (prev !== undefined && prev.after !== e.before)
2868	      throw new DataError(
2869	        `库存流水余量不连续：商品 ${e.product} 仓库 ${e.wh} 流水 #${prev.seq} 后余量 ${prev.after}，` +
2870	          `流水 #${e.seq} 前余量 ${e.before}，数据不一致，拒绝输出对账报表（不自动修复）`,
2871	      );
2872	    lastByCombo.set(key, e);
2873	  }
2874	  for (const [key, e] of lastByCombo) {
2875	    const [pid, wh] = JSON.parse(key) as [string, string];
2876	    const cur = getStock(store.stock, pid, wh);
2877	    if (e.after !== cur)
2878	      throw new DataError(
2879	        `商品 ${pid} 仓库 ${wh} 末笔流水 #${e.seq} 余量 ${e.after} 与当前实存 ${cur} 不一致，` +
2880	          `数据不一致，拒绝输出对账报表（不自动修复）`,
2881	      );
2882	  }
2883	  for (const pid of Object.keys(store.stock)) {
2884	    for (const wh of Object.keys(store.stock[pid])) {
2885	      if (store.stock[pid][wh] !== 0 && !lastByCombo.has(JSON.stringify([pid, wh])))
