2890	    }
2891	  }
2892	  // 调拨两端完整性：同一单据同一商品的调拨（或冲销调拨）必须调出、调入各一条，数量与方向一致
2893	  const sides = new Map<string, LedgerEntry[]>();
2894	  for (const e of store.entries) {
