2911	    const expect = [a.from!, a.to!].sort();
2912	    if (
2913	      a.from !== b.from || a.to !== b.to || a.qty !== b.qty ||
2914	      whPair[0] !== expect[0] || whPair[1] !== expect[1]
2915	    )
