2937	 * 同一单作两端为空期间；不指定起点从零库存开始，不指定终点截至当前。
2938	 * 边界仅接受已成功且有库存流水的单据（冲销单、零差额盘点可用；只有采购或取消
2939	 * 记录的编号不可用；同名采购单不干扰库存单定位），按首次提交顺序（流水序号）
2940	 * 比较，起点晚于终点或单据不存在拒绝。先确定全局边界再按商品/仓库筛选，
2941	 * 不拆开多商品单据或调拨两端。
2942	 */
2943	function runRecon(rest: string[], store: Store): void {
2944	  const args = parseArgs(rest, ['--from', '--to', '--product', '--wh']);
2945	  if (args.positionals.length > 0)
2946	    throw new UsageError(
2947	      '用法：recon [--from <起点单据编号>] [--to <终点单据编号>] [--product <商品编号>] [--wh <仓库>]',
2948	    );
