2956	
2957	  // 出报表前核对完整库存流水；不一致明确报错，不输出部分报表、不自动修复
2958	  verifyLedgerIntegrity(store);
2959	
2960	  // 边界定位（全局）：仅接受有库存流水的单据编号；采购编号空间独立，同名采购不干扰定位
2961	  const docLastSeq = nullProto<Record<string, number>>();
2962	  for (const e of store.entries) docLastSeq[e.doc] = e.seq;
2963	  const boundary = (id: string, label: string): number => {
2964	    const seq = docLastSeq[id];
2965	    if (seq !== undefined) return seq;
2966	    if (store.purchases[id] !== undefined)
2967	      throw new BizError(`${label}单据 ${id} 只有采购登记记录，没有库存流水，不能用作期间边界`);
2968	    if (store.cancels[id] !== undefined)
2969	      throw new BizError(`${label}单据 ${id} 只有取消记录，没有库存流水，不能用作期间边界`);
2970	    if (store.poTransfers[id] !== undefined)
2971	      throw new BizError(`${label}单据 ${id} 只有采购转单记录，没有库存流水，不能用作期间边界`);
2972	    if (store.reversals[id] !== undefined) {
2973	      const orig = store.reversals[id].orig;
2974	      if (store.poTransfers[orig] !== undefined)
2975	        throw new BizError(`${label}单据 ${id} 是冲销采购转单的冲销单，没有库存流水，不能用作期间边界`);
2976	      throw new BizError(`${label}单据 ${id} 是冲销取消单的冲销单，没有库存流水，不能用作期间边界`);
2977	    }
2978	    throw new BizError(`${label}单据 ${id} 不存在或没有库存流水，不能用作期间边界`);
2979	  };
2980	  const startBound = fromId === undefined ? 0 : boundary(fromId, '起点');
2981	  const endBound = toId === undefined ? Number.POSITIVE_INFINITY : boundary(toId, '终点');
2982	  if (startBound > endBound)
2983	    throw new BizError(`起点单据 ${fromId} 的提交顺序晚于终点单据 ${toId}，期间无效，拒绝生成报表`);
2984	
2985	  // 先确定全局边界，再按商品/仓库筛选；期间 = (起点末笔流水, 终点末笔流水]
2986	  const beginOf = nullProto<Record<string, Record<string, number>>>();
2987	  const endOf = nullProto<Record<string, Record<string, number>>>();
2988	  const combos = new Map<string, ReconCombo>();
2989	  const periodEntries: LedgerEntry[] = [];
2990	  for (const e of store.entries) {
2991	    if (e.seq <= startBound) (beginOf[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
2992	    if (e.seq <= endBound) (endOf[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
2993	    const match = (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid);
2994	    if (!match) continue;
2995	    const key = JSON.stringify([e.product, e.wh]);
2996	    if (e.seq <= endBound && !combos.has(key)) {
2997	      combos.set(key, {
2998	        pid: e.product, wh: e.wh, begin: 0, end: 0,
2999	        inc: 0n, dec: 0n, subtotals: new Map(), hasFlow: false,
3000	      });
3001	    }
3002	    if (e.seq > startBound && e.seq <= endBound) periodEntries.push(e);
3003	  }
3004	  for (const c of combos.values()) {
3005	    c.begin = beginOf[c.pid]?.[c.wh] ?? 0;
3006	    c.end = endOf[c.pid]?.[c.wh] ?? 0;
3007	  }
3008	  for (const e of periodEntries) {
3009	    const c = combos.get(JSON.stringify([e.product, e.wh]))!;
3010	    c.hasFlow = true;
3011	    const delta = BigInt(e.after) - BigInt(e.before);
3012	    if (delta > 0n) c.inc += delta;
3013	    else c.dec += -delta;
3014	    c.subtotals.set(e.type, (c.subtotals.get(e.type) ?? 0n) + delta);
3015	  }
3016	
3017	  // 原单冲销状态以终点时刻为准：终点之后的冲销不影响历史报表
3018	  const revLastSeq = nullProto<Record<string, number>>();
3019	  for (const e of store.entries) if (REV_ENTRY_TYPES.has(e.type)) revLastSeq[e.doc] = e.seq;
3020	  const reversedByEnd = nullProto<Record<string, string>>();
3021	  for (const [revId, rec] of Object.entries(store.reversals)) {
3022	    const seq = revLastSeq[revId];
3023	    if (seq !== undefined && seq <= endBound) reversedByEnd[rec.orig] = revId;
3024	  }
3025	
3026	  const fromDesc = fromId === undefined ? '零库存（无起点）' : `单据 ${fromId} 全部流水完成后（不含该单）`;
3027	  const toDesc = toId === undefined ? '当前（无终点）' : `单据 ${toId} 全部流水完成后（含该单）`;
3028	  const scope = [pid !== undefined ? `商品=${pid}` : null, wid !== undefined ? `仓库=${wid}` : null]
3029	    .filter(Boolean)
3030	    .join(' ');
3031	  console.log('期间库存对账报表：');
3032	  console.log(`期间：起点=${fromDesc}；终点=${toDesc}`);
3033	  console.log(scope === '' ? '筛选：无（覆盖全库）' : `筛选：${scope}`);
3034	  console.log(
3035	    `数据核对通过：完整流水 ${store.entries.length} 条余量连续、调拨两端完整、末笔余量与当前实存一致`,
3036	  );
3037	
3038	  // 展示期初或期末非零及期间有流水的组合，按商品、仓库标识升序
3039	  const shown = [...combos.values()]
3040	    .filter((c) => c.begin !== 0 || c.end !== 0 || c.hasFlow)
3041	    .sort((a, b) =>
3042	      a.pid < b.pid ? -1 : a.pid > b.pid ? 1 : a.wh < b.wh ? -1 : a.wh > b.wh ? 1 : 0,
3043	    );
3044	  if (shown.length === 0) {
3045	    console.log('（无匹配组合：所选范围内期初、期末均为零且期间无流水）');
3046	  }
3047	  for (const c of shown) {
3048	    const net = c.inc - c.dec;
3049	    if (BigInt(c.begin) + net !== BigInt(c.end))
3050	      throw new DataError(
3051	        `商品 ${c.pid} 仓库 ${c.wh} 期初 ${c.begin} + 净变动 ${net} 与期末 ${c.end} 不符，` +
3052	          `数据不一致，拒绝输出对账报表（不自动修复）`,
3053	      );
3054	    console.log(
3055	      `组合 商品=${c.pid} 仓库=${c.wh}：期初 ${c.begin}，期间增加 ${c.inc}，期间减少 ${c.dec}，` +
3056	        `净变动 ${fmtSignedBig(net)}，期末 ${c.end}（期初 + 增加 - 减少 = 期末）`,
3057	    );

