3471	interface ReplenishSuggestion {
3472	  pid: string;
3473	  wh: string;
3474	  min: number;
3475	  target: number;
3476	  onHand: number; // 本仓实存（非负安全整数）
3477	  pending: bigint; // 本仓待到货合计（精确整数，可超安全整数范围）
3478	  projected: bigint; // 预计量 = 实存 + 待到货合计
3479	  triggered: boolean; // 预计量不高于下限才触发
3480	  gap: bigint; // 缺口 = 目标 - 预计量（仅触发时为正）
3481	  transfers: { from: string; qty: bigint }[]; // 各调拨来源及数量（来源仓升序）
3482	  transferTotal: bigint; // 调拨合计
3483	  purchase: bigint; // 采购量 = 调拨后剩余缺口（可为零）
3484	}
3485	
3486	/**
3487	 * 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商），
3488	 * 待到货 = 订购 - 有效到货 - 有效取消；BigInt 精确累计，超安全整数合计不舍入。
3489	 * 补货建议与方案快照/核对共用同一计算，保证口径一致。
3490	 */
3491	function pendingTotals(store: Store): Record<string, Record<string, bigint>> {
3492	  const pendingByCombo = nullProto<Record<string, Record<string, bigint>>>();
3493	  for (const poId of Object.keys(store.purchases)) {
3494	    const po = store.purchases[poId];
3495	    const { remaining } = purchaseProgress(store, poId); // 待到货 = 订购 - 有效到货 - 有效取消
3496	    for (const [pid, wait] of Object.entries(remaining)) {
3497	      if (wait === 0n) continue;
3498	      const byWh = (pendingByCombo[pid] ??= nullProto<Record<string, bigint>>());
3499	      byWh[po.wh] = (byWh[po.wh] ?? 0n) + wait;
3500	    }
3501	  }
3502	  return pendingByCombo;
3503	}
3504	
3505	/**
3506	 * 跨仓补货建议（只读计算，不写文件、不改库存或采购；同状态结果一致）：
3507	 * 每个已配置（商品, 仓库）组合的预计量 = 本仓实存 + 本仓待到货合计
3508	 * （收货仓为本仓的全部采购单：待到货 = 订购 - 有效到货 - 有效取消，不限供应商；
3509	 * 其他仓库存不计入）。预计量不高于下限才触发，缺口 = 目标 - 预计量。
3510	 * 按商品分别分配：同商品其他已配置仓实存超过自身目标的部分可供调拨（待收不可调，
3511	 * 未配置仓既不产生需求也不提供调拨）；缺货仓、来源仓各按标识升序依次取量，
3512	 * 整份建议对来源的累计分配不超过可供量；剩余缺口即采购量。
3513	 * 合计、比较与分配一律用 BigInt 精确整数计算。
3514	 */
3515	function computeReplenish(store: Store): ReplenishSuggestion[] {
3516	  // 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商）
3517	  const pendingByCombo = pendingTotals(store);
3518	
3519	  const combos: ReplenishSuggestion[] = [];
3520	  for (const pid of Object.keys(store.rules).sort()) {
3521	    for (const wh of Object.keys(store.rules[pid]).sort()) {
3522	      const rule = store.rules[pid][wh];
3523	      const onHand = getStock(store.stock, pid, wh); // 无库存记录视为零
3524	      const pending = pendingByCombo[pid]?.[wh] ?? 0n;
3525	      const projected = BigInt(onHand) + pending;
3526	      const triggered = projected <= BigInt(rule.min); // 不高于下限才触发
3527	      combos.push({
3528	        pid, wh, min: rule.min, target: rule.target, onHand, pending, projected,
3529	        triggered, gap: triggered ? BigInt(rule.target) - projected : 0n,
3530	        transfers: [], transferTotal: 0n, purchase: 0n,
3531	      });
3532	    }
3533	  }
3534	
3535	  // 按商品分别分配调拨：缺货仓与来源仓均按标识升序（combos 已按商品、仓库升序）
3536	  const byProduct = new Map<string, ReplenishSuggestion[]>();
3537	  for (const c of combos) {
3538	    const list = byProduct.get(c.pid) ?? [];
3539	    list.push(c);
3540	    byProduct.set(c.pid, list);
3541	  }
3542	  for (const list of byProduct.values()) {
3543	    // 可供调拨量 = 实存 - 自身目标（仅实存超过目标的部分；待收不可调）
3544	    const sources = list
3545	      .filter((c) => BigInt(c.onHand) > BigInt(c.target))
3546	      .map((c) => ({ wh: c.wh, available: BigInt(c.onHand) - BigInt(c.target) }));
3547	    for (const deficit of list) {
3548	      if (!deficit.triggered) continue;
3549	      let rest = deficit.gap;
3550	      for (const src of sources) {
3551	        if (rest === 0n) break;
3552	        if (src.wh === deficit.wh || src.available === 0n) continue; // 缺货仓实存必低于目标，防御性跳过
3553	        const take = src.available < rest ? src.available : rest;
3554	        deficit.transfers.push({ from: src.wh, qty: take });
3555	        deficit.transferTotal += take;
3556	        src.available -= take; // 整份建议对来源的累计分配不超过可供量
3557	        rest -= take;
3558	      }
3559	      deficit.purchase = rest; // 剩余缺口即采购量（可为零）
3560	    }
3561	  }
3562	  return combos;
3563	}
3564	
3565	function runReplenish(rest: string[], store: Store): void {
3566	  const args = parseArgs(rest, []);
3567	  if (args.positionals.length > 0) throw new UsageError('用法：replenish');
3568	  if (Object.keys(store.rules).length === 0) {
3569	    console.log('未配置任何补货规则，无补货建议（可先用 rule set 为商品与仓库设置下限与目标）。');
3570	    return;
3571	  }
3572	  const combos = computeReplenish(store);
3573	  const triggeredCount = combos.filter((c) => c.triggered).length;
3574	  console.log(`补货建议（规则 ${combos.length} 条，触发 ${triggeredCount} 条）：`);
3575	  for (const c of combos) {
3576	    console.log(
3577	      `商品 ${c.pid} 仓库 ${c.wh}：下限 ${c.min}，目标 ${c.target}，实存 ${c.onHand}，` +
3578	        `待到货合计 ${c.pending}，预计量 ${c.projected}，` +
3579	        (c.triggered ? `触发补货，缺口 ${c.gap}` : '未触发'),
3580	    );
3581	    if (c.triggered) {
3582	      for (const t of c.transfers) console.log(`  调拨 ${t.from} -> ${c.wh}：${t.qty}`);
3583	      console.log(`  调拨合计 ${c.transferTotal}，采购量 ${c.purchase}`);
3584	    }
3585	  }
3586	  if (triggeredCount === 0) console.log('所有组合预计量均高于下限，无缺货，无需补货。');
3587	}
