4000	/**
4001	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
4002	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
4003	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
4004	 */
4005	function runImport(rest: string[], dataDir: string): void {
4006	  const args = parseArgs(rest, ['--file']);
4007	  const file = args.flags['--file'];
4008	  if (file === undefined || args.positionals.length > 0)
4009	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
4010	
4011	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
4012	  const requests = parseImportFile(readImportFile(file));
4013	
4014	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
4015	  const store = loadStore(dataDir);
4016	  const ledger = new Ledger(store);
4017	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
4018	  const blocks: string[] = [];
4019	  let newCount = 0;
4020	
4021	  requests.forEach((r, i) => {
4022	    const pos = `第 ${i + 1}/${requests.length} 项`;
4023	    // 模拟阶段的业务拒绝同样标注列表位置与原因
4024	    const apply = (): ApplyOutcome => {
4025	      switch (r.kind) {
4026	        case 'doc': return ledger.applyDoc(r.req);
4027	        case 'count': return ledger.applyCount(r.req);
4028	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
4029	        case 'po': return ledger.applyPurchase(r.req);
4030	        case 'arrival': return ledger.applyArrival(r.req);
4031	        case 'cancel': return ledger.applyCancel(r.req);
4032	        case 'return': return ledger.applyReturn(r.req);
4033	        case 'transfer': return ledger.applyTransfer(r.req);
4034	      }
4035	    };
4036	    let outcome: ApplyOutcome;
4037	    try {
4038	      outcome = apply();
4039	    } catch (e) {
4040	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
4041	      throw e;
4042	    }
4043	    const id =
4044	      r.kind === 'reverse' ? r.docId
4045	      : r.kind === 'po' ? r.req.poId
4046	      : r.kind === 'arrival' ? r.req.arrId
4047	      : r.kind === 'cancel' ? r.req.canId
4048	      : r.kind === 'return' ? r.req.retId
4049	      : r.kind === 'transfer' ? r.req.tId
4050	      : r.req.docId;
4051	
4052	    let status: string;
4053	    if (outcome.duplicate) {
4054	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
4055	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
4056	    } else {
4057	      status = '首次生效';
4058	      newCount++;
4059	    }
4060	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
4061	  });
4062	
4063	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
4064	  ledger.commit(dataDir);
4065	
4066	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
4067	  for (const block of blocks) console.log(block);
4068	}
