  // （待收归零，不改库存与流水）；任一子单失败整案不留变动
  const lines: string[] = [];
  for (const t of plan.transfers) {
    const revId = req.transferRevs.get(t.docId)!;
    const outcome = this.applyReversal(revId, t.docId);
    lines.push(`调拨子单 ${t.docId} 由冲销单 ${revId} 整单冲销：`, ...outcome.lines);
  }
